B.bUN=new A.bw(76,"\u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u062d\u0652\u0632\u064f\u0646\u0643\u064e \u0642\u064e\u0648\u0652\u0644\u064f\u0647\u064f\u0645\u0652 \u06d8 \u0625\u0650\u0646\u0651\u064e\u0627 \u0646\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u064a\u064f\u0633\u0650\u0631\u0651\u064f\u0648\u0646\u064e \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0639\u0652\u0644\u0650\u0646\u064f\u0648\u0646\u064e","Falaa yahzunka qauluhum, innaa na'lamu maa yusirruuna wa maa yu'linuun.","Maka jangan sampai ucapan mereka membuat engkau (Muhammad) bersedih hati. Sungguh, Kami mengetahui apa yang mereka rahasiakan dan apa yang mereka nyatakan.")
B.bVl=new A.bw(77,"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0631\u064e \u0671\u0644\u0652\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064f \u0623\u064e\u0646\u0651\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0670\u0647\u064f \u0645\u0650\u0646 \u0646\u0651\u064f\u0637\u0652\u0641\u064e\u0629\u064d \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0648\u064e \u062e\u064e\u0635\u0650\u064a\u0645\u064c \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064c","Awalam yaral-insaanu annaa khalaqnaahu min nuthfatin fa-idzaa huwa khashiimum mubiin.","Dan tidakkah manusia memperhatikan bahwa Kami menciptakannya dari setetes mani, ternyata dia menjadi musuh yang nyata!")
B.bUj=new A.bw(78,"\u0648\u064e\u0636\u064e\u0631\u064e\u0628\u064e \u0644\u064e\u0646\u064e\u0627 \u0645\u064e\u062b\u064e\u0644\u064b\u0627 \u0648\u064e\u0646\u064e\u0633\u0650\u0649\u064e \u062e\u064e\u0644\u0652\u0642\u064e\u0647\u064f\u06e5 \u06d6 \u0642\u064e\u0627\u0644\u064e \u0645\u064e\u0646 \u064a\u064f\u062d\u0652\u0649\u0650 \u0671\u0644\u0652\u0639\u0650\u0638\u064e\u0670\u0645\u064e \u0648\u064e\u0647\u0650\u0649\u064e \u0631\u064e\u0645\u0650\u064a\u0645\u064c","Wa dharaba lanaa matsalaw wa nasiya khalqah, qaala may yuhyil-'izhaama wa hiya ramiim.",'Dan dia membuat perumpamaan bagi Kami dan melupakan asal kejadiannya; dia berkata, "Siapakah yang dapat menghidupkan tulang-belulang yang telah hancur luluh?"')
B.bUI=new A.bw(79,"\u0642\u064f\u0644\u0652 \u064a\u064f\u062d\u0652\u064a\u0650\u064a\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u0649\u0653 \u0623\u064e\u0646\u0634\u064e\u0623\u064e\u0647\u064e\u0627\u0653 \u0623\u064e\u0648\u0651\u064e\u0644\u064e \u0645\u064e\u0631\u0651\u064e\u0629\u064d \u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u062e\u064e\u0644\u0652\u0642\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064c","Qul yuhyiihal-ladziii ansya-ahaaa awwala marrah, wa huwa bikulli khalqin 'aliim.",'Katakanlah (Muhammad), "Yang akan menghidupkannya ialah (Allah) yang menciptakannya pertama kali. Dan Dia Maha Mengetahui tentang segala makhluk,')
B.bUD=new A.bw(80,"\u0671\u0644\u0651\u064e\u0630\u0650\u0649 \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0634\u0651\u064e\u062c\u064e\u0631\u0650 \u0671\u0644\u0652\u0623\u064e\u062e\u0652\u0636\u064e\u0631\u0650 \u0646\u064e\u0627\u0631\u064b\u0627 \u0641\u064e\u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064f\u0645 \u0645\u0651\u0650\u0646\u0652\u0647\u064f \u062a\u064f\u0648\u0642\u0650\u062f\u064f\u0648\u0646\u064e","Al-ladzii ja'ala lakum minasy-syajaril-akhdhari naaran fa-idzaaa antum minhu tuuqiduun.",'yaitu (Allah) yang menjadikan api untukmu dari kayu yang hijau, maka seketika itu kamu menyalakan (api) dari kayu itu."')
B.bUL=new A.bw(81,"\u0623\u064e\u0648\u064e\u0644\u064e\u064a\u0652\u0633\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u0649 \u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0628\u0650\u0642\u064e\u0670\u062f\u0650\u0631\u064d \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u064a\u064e\u062e\u0652\u0644\u064f\u0642\u064e \u0645\u0650\u062b\u0652\u0644\u064e\u0647\u064f\u0645 \u06da \u0628\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0652\u062e\u064e\u0644\u0651\u064e\u0670\u0642\u064f \u0671\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0645\u064f","Awa laisal-ladzii khalaqas-samaawaati wal-ardha biqaadirin 'alaaa ay yakhluqa mitslahum, balaa wa huwal-khallaaqul-'aliim.","Dan bukankah (Allah) yang menciptakan langit dan bumi, berkuasa menciptakan kembali jasad-jasad mereka yang serupa itu? Benar, dan Dia Maha Pencipta, Maha Mengetahui.")
