B.Nm=s([4286267364,4287972351],t.t)
B.bWf=new A.dj("mot-1","Jangan pernah menyerah ketika doamu belum terkabul. Jika kamu mampu bersabar, Allah mampu memberikan lebih dari apa yang kamu minta.","\u0625\u0650\u0646\u0651\u064e \u0645\u064e\u0639\u064e \u0627\u0644\u0652\u0639\u064f\u0633\u0652\u0631\u0650 \u064a\u064f\u0633\u0652\u0631\u064b\u0627","QS. Al-Insyirah: 6","motivasi","Motivasi & Hijrah",B.Nm)
B.aQ3=s([4285141451,4280645116],t.t)
B.bWg=new A.dj("mot-2","Dunia ini hanya tiga hari: Hari kemarin yang telah berlalu bersama apa yang ada padanya; Hari esok yang mungkin tak kan kau jumpai; Dan hari ini yang menjadi milikmu, maka beramallah di dalamnya.",null,"Hasan Al-Basri","motivasi","Motivasi & Hijrah",B.aQ3)
B.aQ_=s([4283039968,4287507938],t.t)
B.bWC=new A.dj("mot-3","Barangsiapa yang menempuh suatu jalan untuk mencari ilmu, maka Allah akan memudahkan baginya jalan menuju surga.","\u0645\u064e\u0646\u0652 \u0633\u064e\u0644\u064e\u0643\u064e \u0637\u064e\u0631\u0650\u064a\u0642\u064b\u0627 \u064a\u064e\u0644\u0652\u062a\u064e\u0645\u0650\u0633\u064f \u0641\u0650\u064a\u0647\u0650 \u0639\u0650\u0644\u0652\u0645\u064b\u0627 \u0633\u064e\u0647\u0651\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0647\u064f \u0628\u0650\u0647\u0650 \u0637\u064e\u0631\u0650\u064a\u0642\u064b\u0627 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u0650","HR. Muslim no. 2699","motivasi","Motivasi & Hijrah",B.aQ_)
B.aPP=s([4279343502,4281921405],t.t)
B.bWI=new A.dj("mot-4","Hijrah bukan tentang menjadi lebih baik dari orang lain, melainkan tentang menjadi lebih baik dari dirimu yang kemarin di hadapan Allah.",null,"Kutipan Mutiara","motivasi","Motivasi & Hijrah",B.aPP)
B.aQb=s([4294465446,4294924376],t.t)
B.bWE=new A.dj("mot-5","Amalan yang paling dicintai oleh Allah adalah amalan yang kontinu (berkelanjutan) meskipun sedikit.","\u0623\u064e\u062d\u064e\u0628\u0651\u064f \u0627\u0644\u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u0650 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u062f\u0652\u0648\u064e\u0645\u064f\u0647\u064e\u0627 \u0648\u064e\u0625\u0650\u0646\u0652 \u0642\u064e\u0644\u0651\u064e","HR. Bukhari & Muslim","motivasi","Motivasi & Hijrah",B.aQb)
B.aQ1=s([4284188389,4281782748],t.t)
B.bWq=new A.dj("mot-6","Kebaikan yang engkau tanam hari ini, kelak akan menjadi peneduh di saat terik hari pembalasan.",null,"Ibnu Qayyim Al-Jauziyyah","motivasi","Motivasi & Hijrah",B.aQ1)
B.aPK=s([4278211284,4282606839],t.t)
B.bWr=new A.dj("sab-1","Allah tidak membebani seseorang melainkan sesuai dengan kesanggupannya.","\u0644\u064e\u0627 \u064a\u064f\u0643\u064e\u0644\u0651\u0650\u0641\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0646\u064e\u0641\u0652\u0633\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064f\u0633\u0652\u0639\u064e\u0647\u064e\u0627","QS. Al-Baqarah: 286","sabar","Sabar & Ujian",B.aPK)
B.Nn=s([4286513407,4292935935],t.t)
B.bWc=new A.dj("sab-2","Kesabaran itu ada dua macam: sabar atas sesuatu yang tidak kau sukai dan sabar menahan diri dari apa yang kau sukai tapi dilarang.",null,"Ali bin Abi Thalib","sabar","Sabar & Ujian",B.Nn)
B.aPV=s([4281089616,4281637083],t.t)
B.bWl=new A.dj("sab-3","Boleh jadi kamu membenci sesuatu, padahal ia amat baik bagimu, dan boleh jadi kamu menyukai sesuatu, padahal ia amat buruk bagimu. Allah mengetahui, sedang kamu tidak mengetahui.","\u0648\u064e\u0639\u064e\u0633\u064e\u0649\u0670 \u0623\u064e\u0646 \u062a\u064e\u0643\u0652\u0631\u064e\u0647\u064f\u0648\u0627 \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0648\u064e\u0647\u064f\u0648\u064e \u062e\u064e\u064a\u0652\u0631\u064c \u0644\u0651\u064e\u0643\u064f\u0645\u0652","QS. Al-Baqarah: 216","sabar","Sabar & Ujian",B.aPV)
B.aPQ=s([4279455326,4285641344],t.t)
B.bWm=new A.dj("sab-4","Ketahuilah bahwa kemenangan bersama kesabaran, kelapangan bersama kesempitan, dan bersama kesulitan ada kemudahan.","\u0648\u064e\u0627\u0639\u0652\u0644\u064e\u0645\u0652 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0646\u0651\u064e\u0635\u0652\u0631\u064e \u0645\u064e\u0639\u064e \u0627\u0644\u0635\u0651\u064e\u0628\u0652\u0631\u0650\u060c \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0652\u0641\u064e\u0631\u064e\u062c\u064e \u0645\u064e\u0639\u064e \u0627\u0644\u0652\u0643\u064e\u0631\u0652\u0628\u0650","HR. Ahmad & Tirmidzi","sabar","Sabar & Ujian",B.aPQ)
B.Nl=s([4284829347,4293570504],t.t)
B.bWz=new A.dj("sab-5","Jangan bersedih atas apa yang telah pergi darimu, karena jika Allah menakdirkannya untukmu, ia takkan pernah menjadi milik orang lain.",null,"Imam Syafi'i","sabar","Sabar & Ujian",B.Nl)
B.aPZ=s([4282738908,4289751731],t.t)
B.bWj=new A.dj("sab-6","Bila takdir tidak berjalan sesuai rencanamu, ingatlah bahwa takdir Allah selalu berjalan dengan hikmah terindah untukmu.",null,"Umar bin Khattab","sabar","Sabar & Ujian",B.aPZ)
B.aPM=s([4278952800,4282170002],t.t)
B.bWA=new A.dj("syu-1","Sesungguhnya jika kamu bersyukur, pasti Kami akan menambah (nikmat) kepadamu, dan jika kamu mengingkari (nikmat-Ku), maka sesungguhnya azab-Ku sangat pedih.","\u0644\u064e\u0626\u0650\u0646 \u0634\u064e\u0643\u064e\u0631\u0652\u062a\u064f\u0645\u0652 \u0644\u064e\u0623\u064e\u0632\u0650\u064a\u062f\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652","QS. Ibrahim: 7","syukur","Syukur & Rezeki",B.aPM)
B.aQa=s([4294089034,4294101324],t.t)
B.bWs=new A.dj("syu-2","Bukan harta melimpah yang membuat seseorang kaya, tetapi hati yang selalu merasa cukup (qana'ah) itulah kekayaan sejati.","\u0644\u064e\u064a\u0652\u0633\u064e \u0627\u0644\u0652\u063a\u0650\u0646\u064e\u0649 \u0639\u064e\u0646\u0652 \u0643\u064e\u062b\u0652\u0631\u064e\u0629\u0650 \u0627\u0644\u0652\u0639\u064e\u0631\u064e\u0636\u0650\u060c \u0648\u064e\u0644\u064e\u0643\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u063a\u0650\u0646\u064e\u0649 \u063a\u0650\u0646\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0641\u0652\u0633\u0650","HR. Bukhari no. 6446","syukur","Syukur & Rezeki",B.aQa)
B.aPX=s([4282022869,4282015859],t.t)
B.bWB=new A.dj("syu-3","Barangsiapa bertakwa kepada Allah niscaya Dia akan membukakan jalan keluar baginya, dan memberinya rezeki dari arah yang tiada disangka-sangkanya.","\u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u062a\u0651\u064e\u0642\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u062c\u0652\u0639\u064e\u0644 \u0644\u0651\u064e\u0647\u064f \u0645\u064e\u062e\u0652\u0631\u064e\u062c\u064b\u0627 \u0648\u064e\u064a\u064e\u0631\u0652\u0632\u064f\u0642\u0652\u0647\u064f \u0645\u0650\u0646\u0652 \u062d\u064e\u064a\u0652\u062b\u064f \u0644\u064e\u0627 \u064a\u064e\u062d\u0652\u062a\u064e\u0633\u0650\u0628\u064f","QS. At-Talaq: 2-3","syukur","Syukur & Rezeki",B.aPX)
B.aPS=s([4280129388,4287887801],t.t)
B.bWJ=new A.dj("syu-4","Lihatlah kepada orang yang berada di bawahmu dalam urusan dunia, dan jangan melihat kepada orang yang berada di atasmu, agar engkau tidak meremehkan nikmat Allah kepadamu.","\u0627\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649 \u0645\u064e\u0646\u0652 \u0623\u064e\u0633\u0652\u0641\u064e\u0644\u064e \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u0627\u064e \u062a\u064e\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649 \u0645\u064e\u0646\u0652 \u0647\u064f\u0648\u064e \u0641\u064e\u0648\u0652\u0642\u064e\u0643\u064f\u0645\u0652","HR. Muslim no. 2963","syukur","Syukur & Rezeki",B.aPS)
B.aQ0=s([4283323592,4287599867],t.t)
B.bWx=new A.dj("syu-5","Rezeki yang telah ditetapkan untukmu tidak akan pernah tertukar atau diambil oleh orang lain. Tenangkan hatimu, berikhtiar dan bertawakallah.",null,"Hasan Al-Basri","syukur","Syukur & Rezeki",B.aQ0)
B.bWH=new A.dj("doa-1","Berdoalah kepada-Ku, niscaya akan Kuperkenankan bagimu.","\u0627\u062f\u0652\u0639\u064f\u0648\u0646\u0650\u064a \u0623\u064e\u0633\u0652\u062a\u064e\u062c\u0650\u0628\u0652 \u0644\u064e\u0643\u064f\u0645\u0652","QS. Ghafir: 60","doa","Doa & Taubat",B.Nn)
B.aQ5=s([4287243143,4293476439],t.t)
B.bWD=new A.dj("doa-2","Aku tidak pernah mengkhawatirkan apakah doaku akan dikabulkan atau tidak, karena yang aku khawatirkan adalah jika aku tidak diberi hidayah untuk berdoa.",null,"Umar bin Khattab","doa","Doa & Taubat",B.aQ5)
B.aPU=s([4281030774,4283319158],t.t)
B.bWv=new A.dj("doa-3","Katakanlah: 'Hai hamba-hamba-Ku yang melampaui batas terhadap diri mereka sendiri, janganlah kamu berputus asa dari rahmat Allah. Sesungguhnya Allah mengampuni dosa-dosa semuanya.'","\u0642\u064f\u0644\u0652 \u064a\u064e\u0627 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0633\u0652\u0631\u064e\u0641\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u0644\u064e\u0627 \u062a\u064e\u0642\u0652\u0646\u064e\u0637\u064f\u0648\u0627 \u0645\u0650\u0646 \u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0629\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650","QS. Az-Zumar: 53","doa","Doa & Taubat",B.aPU)
B.aPY=s([4282274129,4292791204],t.t)
B.bWe=new A.dj("doa-4","Doa adalah senjata orang mukmin, tiang agama, dan cahaya langit serta bumi.","\u0627\u0644\u062f\u0651\u064f\u0639\u064e\u0627\u0621\u064f \u0633\u0650\u0644\u0627\u064e\u062d\u064f \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650 \u0648\u064e\u0639\u0650\u0645\u064e\u0627\u062f\u064f \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u0650 \u0648\u064e\u0646\u064f\u0648\u0631\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0623\u064e\u0631\u0652\u0636\u0650","HR. Al-Hakim","doa","Doa & Taubat",B.aPY)
