B.bWo=new A.dj("cin-2","Sebaik-baik kalian adalah orang yang paling baik terhadap keluarganya, dan aku adalah orang yang paling baik terhadap keluargaku.","\u062e\u064e\u064a\u0652\u0631\u064f\u0643\u064f\u0645\u0652 \u062e\u064e\u064a\u0652\u0631\u064f\u0643\u064f\u0645\u0652 \u0644\u0623\u064e\u0647\u0652\u0644\u0650\u0647\u0650 \u0648\u064e\u0623\u064e\u0646\u064e\u0627 \u062e\u064e\u064a\u0652\u0631\u064f\u0643\u064f\u0645\u0652 \u0644\u0623\u064e\u0647\u0652\u0644\u0650\u064a","HR. Tirmidzi no. 3895","cinta","Cinta & Keluarga",B.aQ6)
B.aQ9=s([4293827751,4294958561],t.t)
